import type { ChartCandle } from "./types";

export const DEFAULT_LIVE_CANDLES = 50;

export type GoptionTick = {
  readonly symbol: string;
  readonly close: number;
  readonly time: number;
  readonly isClosed?: boolean | undefined;
};

export interface GoptionLiveCandlesOptions {
  readonly initialCandles?: readonly ChartCandle[];
  readonly intervalSeconds?: number;
  readonly maxCandles?: number;
}

export type LiveCandleSeedDecision =
  | { readonly kind: "replace"; readonly candles: ChartCandle[] }
  | { readonly kind: "keep" };

export function parseGoptionTick(raw: string): GoptionTick | null {
  try {
    const data = JSON.parse(raw) as Record<string, unknown>;
    const close =
      typeof data["close"] === "number" ? data["close"] : Number.NaN;
    const time = normalizeTickTime(data["time"]);
    const symbol = typeof data["symbol"] === "string" ? data["symbol"] : "";
    if (!symbol || !Number.isFinite(close) || !Number.isFinite(time))
      return null;
    return { symbol, close, time, isClosed: booleanValue(data["is_closed"]) };
  } catch {
    return null;
  }
}

export function seedLiveCandles(
  initialCandles: readonly ChartCandle[] | undefined,
  maxCandles: number,
): ChartCandle[] {
  if (!initialCandles?.length) return [];
  return initialCandles
    .slice(-safeLiveCandleCap(maxCandles))
    .map((candle) => ({ ...candle }));
}

/** Estende o seed com uma vela synthetic no bucket corrente caso o último
 *  candle histórico seja mais antigo. Padrão TradingView: o chart pinta JÁ
 *  com a vela do bucket corrente posicionada — o primeiro tick SSE só
 *  muta o close, sem causar shift visual.
 *
 *  Operador (28/05/2026): "todo trade começa ruim a vela ai vem o dado
 *  atual e arruma, tinha que vir já acertada hora que renderizar".
 */
export function extendSeedToCurrentBucket(
  seed: readonly ChartCandle[],
  intervalSeconds: number,
  maxCandles: number,
  nowSeconds: number = Math.floor(Date.now() / 1000),
): ChartCandle[] {
  if (seed.length === 0) return [];
  const last = seed[seed.length - 1];
  if (!last) return [...seed];
  const interval = Math.max(1, Math.floor(intervalSeconds));
  const currentBucket = Math.floor(nowSeconds / interval) * interval;
  if (currentBucket <= last.time) return [...seed];
  const synthetic: ChartCandle = {
    time: currentBucket,
    open: last.close,
    high: last.close,
    low: last.close,
    close: last.close,
    value: last.close,
  };
  const merged = [...seed, synthetic];
  const cap = safeLiveCandleCap(maxCandles);
  return merged.length > cap ? merged.slice(merged.length - cap) : merged;
}

/** Copy a historical seed into the live candle buffer.
 *
 * Legacy parity (P4 Track E): no minimum-length gate — a partial Matrix
 * history is still seeded so the chart paints immediately. The legacy
 * MIN_CANDLES_FOR_TRADE_CHART = 3 lives in the parent gate, not here.
 *
 * `minimumSeedCandles` is retained for callsite compatibility but is now
 * a no-op so the third arg can be removed in a follow-up sweep.
 *
 * Example: `seedCompleteLiveCandles(candles3, 30, 3)` returns a 3-candle copy.
 */
export function seedCompleteLiveCandles(
  initialCandles: readonly ChartCandle[] | undefined,
  maxCandles: number,
  _minimumSeedCandles: number,
): ChartCandle[] {
  return seedLiveCandles(initialCandles, maxCandles);
}

/** Check whether a live buffer has any seeded candles.
 *
 * Legacy parity: ticks extend a partial buffer instead of being dropped while
 * waiting for a 30-candle seed (legacy `lastDataLengthRef.current === 0` ->
 * performFullSync; otherwise update last bar in place).
 *
 * Example: `hasCompleteLiveCandleSeed(candles3)` returns true.
 */
export function hasCompleteLiveCandleSeed(
  candles: readonly ChartCandle[],
  _minimumSeedCandles?: number,
): boolean {
  return candles.length > 0;
}

/** Decide whether a Matrix history refetch should replace the live buffer.
 *
 * Legacy parity: never reject a non-empty Matrix snapshot — replace whenever
 * the new seed is non-empty and not a strict shrink of the current buffer.
 *
 * Example: `resolveLiveCandleSeedUpdate(current3, [], 30)` keeps current.
 */
export function resolveLiveCandleSeedUpdate(
  current: readonly ChartCandle[],
  initialCandles: readonly ChartCandle[] | undefined,
  maxCandles: number,
  _minimumSeedCandles?: number,
): LiveCandleSeedDecision {
  const nextSeed = seedLiveCandles(initialCandles, maxCandles);
  if (nextSeed.length === 0) {
    if (current.length > 0) return { kind: "keep" };
    return { kind: "replace", candles: [] };
  }
  if (hasLiveTickFoldedIntoTail(current, nextSeed)) return { kind: "keep" };
  if (current.length > 0 && nextSeed.length < current.length) {
    return { kind: "keep" };
  }
  if (current.length > 0) {
    const merged = mergeSeedWithLiveTail(current, nextSeed, maxCandles);
    if (merged !== null) return { kind: "replace", candles: merged };
  }
  return { kind: "replace", candles: nextSeed };
}

export function appendTickToLiveCandles(
  prev: readonly ChartCandle[],
  tick: GoptionTick,
  intervalSeconds: number,
  maxCandles: number,
): ChartCandle[] {
  const bucketTime = bucketLiveTickTime(tick.time, intervalSeconds);
  const last = prev[prev.length - 1];
  if (last && bucketTime < last.time) {
    if (shouldPatchSyntheticTail(prev, intervalSeconds))
      return replaceLastLiveCandle(prev, last, tick.close);
    return [...prev];
  }
  if (last && last.time === bucketTime)
    return replaceLastLiveCandle(prev, last, tick.close);
  return appendNewLiveCandle(prev, bucketTime, tick.close, maxCandles);
}

/** Buffer a tick into a ref-managed FIFO list, in chronological order, with
 *  dedup by `tick.time`. WHY ref-managed FIFO: while REST `/api/v2/candles`
 *  is in flight the SSE is already open (snapshot+delta pattern). Ticks
 *  arrive in arbitrary order with respect to REST resolution; we replay them
 *  on top of the historical seed once it lands, so the first paint has
 *  ZERO gap between history and live (Binance/TradingView pattern).
 *
 *  Dedup-by-time keeps the buffer bounded across reconnects and protects
 *  against an SSE retry double-sending the same epoch.
 */
export function bufferPendingTick(
  buffer: readonly GoptionTick[],
  tick: GoptionTick,
  maxBuffer: number = 256,
): GoptionTick[] {
  const filtered = buffer.filter((existing) => existing.time !== tick.time);
  const inserted = insertTickChronologically(filtered, tick);
  const cap = Math.max(1, Math.floor(maxBuffer));
  if (inserted.length <= cap) return inserted;
  return inserted.slice(inserted.length - cap);
}

/** Replay a chronological queue of buffered ticks onto a freshly seeded
 *  candle buffer. WHY chronological: `appendTickToLiveCandles` assumes
 *  monotonic time — replaying out of order would create a candle in a stale
 *  bucket and then immediately overwrite it.
 */
export function replayBufferedTicks(
  seed: readonly ChartCandle[],
  buffer: readonly GoptionTick[],
  intervalSeconds: number,
  maxCandles: number,
): ChartCandle[] {
  let next: ChartCandle[] = [...seed];
  for (const tick of buffer) {
    next = appendTickToLiveCandles(next, tick, intervalSeconds, maxCandles);
  }
  return next;
}

function insertTickChronologically(
  buffer: readonly GoptionTick[],
  tick: GoptionTick,
): GoptionTick[] {
  if (buffer.length === 0) return [tick];
  const lastTime = buffer[buffer.length - 1]?.time ?? Number.NEGATIVE_INFINITY;
  // Fast path: incoming tick is newer than the tail — almost always true for
  // an SSE stream. Avoids the O(n) sort on the hot path.
  if (tick.time >= lastTime) return [...buffer, tick];
  // Slow path: out-of-order delivery (rare; defensive only). Linear insert
  // keeps the buffer chronological without a full sort.
  const next = [...buffer];
  let index = next.length - 1;
  while (index >= 0 && (next[index]?.time ?? 0) > tick.time) index -= 1;
  next.splice(index + 1, 0, tick);
  return next;
}

export function normalizeBrokerSymbol(symbol: string): string {
  const upper = symbol.trim().toUpperCase();
  if (upper === "BTC" || upper === "ETH") return `${upper}USDT`;
  return upper;
}

function booleanValue(value: unknown): boolean | undefined {
  return typeof value === "boolean" ? value : undefined;
}

function normalizeTickTime(value: unknown): number {
  if (typeof value !== "number" || !Number.isFinite(value)) return Number.NaN;
  return value > 10_000_000_000 ? Math.floor(value / 1_000) : value;
}

function replaceLastLiveCandle(
  prev: readonly ChartCandle[],
  last: ChartCandle,
  close: number,
): ChartCandle[] {
  const updated: ChartCandle = {
    time: last.time,
    open: last.open,
    high: Math.max(last.high, close),
    low: Math.min(last.low, close),
    close,
    value: close,
  };
  return [...prev.slice(0, -1), updated];
}

// Padrão TradingView (https://www.tradingview.com/charting-library-docs/latest/
// tutorials/implement_datafeed_tutorial/Streaming-Implementation/): quando o
// tick cai em bucket > last.time, emitimos UMA vela nova abrindo no `last.close`.
// gap-in-time é invisível porque o time-scale opera em logical range (slots
// fixos), e gap-in-price é fechado abrindo a vela no close anterior.
// Não preenchemos buckets intermediários — backfill empurraria velas antigas
// para fora do cap maxCandles e causaria o "scroll lateral" visual que o
// operador relatou como "vela faltando espaço, depois corrige".
function appendNewLiveCandle(
  prev: readonly ChartCandle[],
  bucketTime: number,
  close: number,
  maxCandles: number,
): ChartCandle[] {
  const next = buildNextLiveCandle(prev[prev.length - 1], bucketTime, close);
  const merged = [...prev, next];
  const cap = safeLiveCandleCap(maxCandles);
  return merged.length > cap ? merged.slice(merged.length - cap) : merged;
}

function buildNextLiveCandle(
  last: ChartCandle | undefined,
  bucketTime: number,
  close: number,
): ChartCandle {
  return {
    time: bucketTime,
    open: last?.close ?? close,
    high: close,
    low: close,
    close,
    value: close,
  };
}

function safeLiveCandleCap(value: number): number {
  return Number.isFinite(value)
    ? Math.max(1, Math.floor(value))
    : DEFAULT_LIVE_CANDLES;
}

function hasLiveTickFoldedIntoTail(
  current: readonly ChartCandle[],
  nextSeed: readonly ChartCandle[],
): boolean {
  const currentLast = current[current.length - 1];
  const nextLast = nextSeed[nextSeed.length - 1];
  if (!currentLast || !nextLast) return false;
  if (nextSeed.length !== current.length) return false;
  if (nextLast.time !== currentLast.time) return false;
  if (currentLast.close !== nextLast.close) return true;
  // Wick (rabinho) protection: o tick SSE pode ter expandido high/low entre
  // dois fetches do Matrix. Se o snapshot retorna a mesma vela mas com wick
  // mais curto, manter o estado atual evita que o rabinho desapareça.
  if (currentLast.high > nextLast.high) return true;
  if (currentLast.low < nextLast.low) return true;
  return false;
}

function mergeSeedWithLiveTail(
  current: readonly ChartCandle[],
  nextSeed: readonly ChartCandle[],
  maxCandles: number,
): ChartCandle[] | null {
  const nextLast = nextSeed[nextSeed.length - 1];
  const currentLast = current[current.length - 1];
  if (!nextLast) return null;
  // Issue #187: once SSE has advanced beyond a REST seed, a later stale
  // refetch must not rewrite already-painted closed candles behind that tail.
  const preserveFromTime =
    currentLast && currentLast.time > nextLast.time
      ? nextSeed[0]?.time
      : nextLast.time;
  if (preserveFromTime === undefined) return null;
  const byTime = new Map<number, ChartCandle>();
  for (const candle of nextSeed) byTime.set(candle.time, { ...candle });
  let changed = false;
  for (const candle of current) {
    if (candle.time < preserveFromTime) continue;
    const existing = byTime.get(candle.time);
    if (existing && sameLiveCandle(existing, candle)) continue;
    byTime.set(candle.time, { ...candle });
    changed = true;
  }
  if (!changed) return null;
  return capLiveCandles(
    [...byTime.values()].sort((a, b) => a.time - b.time),
    maxCandles,
  );
}

function sameLiveCandle(left: ChartCandle, right: ChartCandle): boolean {
  return (
    left.time === right.time &&
    left.open === right.open &&
    left.high === right.high &&
    left.low === right.low &&
    left.close === right.close
  );
}

function capLiveCandles(
  candles: readonly ChartCandle[],
  maxCandles: number,
): ChartCandle[] {
  const cap = safeLiveCandleCap(maxCandles);
  return candles.length > cap
    ? candles.slice(candles.length - cap)
    : [...candles];
}

function shouldPatchSyntheticTail(
  candles: readonly ChartCandle[],
  intervalSeconds: number,
): boolean {
  const last = candles[candles.length - 1];
  const previous = candles[candles.length - 2];
  if (!last || !previous) return false;
  // The bucket-current synthetic tail may be far ahead of a stale Matrix seed;
  // the first broker tick should mutate that tail instead of being discarded.
  const interval = Math.max(1, Math.floor(intervalSeconds));
  return last.time - previous.time > interval;
}

function bucketLiveTickTime(time: number, intervalSeconds: number): number {
  const bucket = Math.max(1, intervalSeconds);
  return Math.floor(time / bucket) * bucket;
}

export type EntryAwareYRange = {
  readonly minValue: number;
  readonly maxValue: number;
};

export type HighLow = { readonly high: number; readonly low: number };

/** Compute a Y-axis price range that ALWAYS contains the entry line plus a
 *  visual safety margin. WHY: lightweight-charts auto-scale uses only candle
 *  H/L. When the operator opens a trade and the entry line sits near a wick
 *  edge, every tiny price move shifts the auto-scale and the yellow entry
 *  line visually "walks" across the chart. TradingView/MT5 solve this by
 *  pinning the scale to a deterministic range around the operator's
 *  reference price (entry, SL, TP). We replicate that with a custom range
 *  via `autoscaleInfoProvider`.
 *
 *  Algorithm:
 *    base = [min(candle.low), max(candle.high)] (candle envelope)
 *    expanded = [min(base, entry), max(base, entry)] (entry forced inside)
 *    range = expanded width
 *    pad = max(range * 0.04, expanded.maxValue * 0.0008) (4% range OR 0.08% price)
 *    return [expanded.min - pad, expanded.max + pad]
 *
 *  The price-based floor handles flat markets (range=0 ⇒ collapse) and
 *  early seeds where only one candle is present.
 *
 *  Accepts the structural { high, low } shape so callers can pass either
 *  `ChartCandle` (with `value`) or `TradeMiniCandle` (without `value`).
 *
 *  Example: `computeEntryAwareYRange(candles, 1980, 0.04)` returns a range
 *  enveloping all candles AND the entry at 1980, padded by ~4%.
 */
export function computeEntryAwareYRange(
  candles: readonly HighLow[],
  entryPrice: number | null,
  paddingRatio: number = 0.04,
): EntryAwareYRange | null {
  const seed = resolveYRangeSeed(candles, entryPrice);
  if (seed === null) return null;
  const pad = resolveYRangePad(seed, paddingRatio);
  return { minValue: seed.minValue - pad, maxValue: seed.maxValue + pad };
}

function resolveYRangeSeed(
  candles: readonly HighLow[],
  entryPrice: number | null,
): EntryAwareYRange | null {
  const envelope = candleEnvelope(candles);
  const hasEntry = entryPrice != null && Number.isFinite(entryPrice);
  if (envelope === null && !hasEntry) return null;
  const baseMin = envelope?.minValue ?? entryPrice ?? 0;
  const baseMax = envelope?.maxValue ?? entryPrice ?? 0;
  if (!hasEntry) return { minValue: baseMin, maxValue: baseMax };
  return {
    minValue: Math.min(baseMin, entryPrice as number),
    maxValue: Math.max(baseMax, entryPrice as number),
  };
}

function resolveYRangePad(
  seed: EntryAwareYRange,
  paddingRatio: number,
): number {
  const safePadding = Math.max(0, paddingRatio);
  const rangeWidth = Math.max(0, seed.maxValue - seed.minValue);
  // Floor pad: 0.08% of the max price. Handles flat seeds (rangeWidth = 0)
  // and stops the range from collapsing to a single horizontal line.
  const priceFloor = Math.max(0, seed.maxValue) * 0.0008;
  return Math.max(rangeWidth * safePadding, priceFloor);
}

/** Decide whether the current locked Y range still contains the latest
 *  price within a comfortable margin, or whether the chart should expand
 *  the lock. Returns true when the price is OUTSIDE the inner 90% of the
 *  range (i.e. within 5% of either edge), signalling a re-lock. This matches
 *  the TradingView behaviour where the scale silently expands when price
 *  approaches the edge instead of letting candles clip.
 */
export function shouldExpandLockedYRange(
  range: EntryAwareYRange,
  price: number,
  innerRatio: number = 0.9,
): boolean {
  if (!Number.isFinite(price)) return false;
  const width = range.maxValue - range.minValue;
  if (width <= 0) return true;
  const safeRatio = Math.min(1, Math.max(0, innerRatio));
  const margin = (width * (1 - safeRatio)) / 2;
  const innerMin = range.minValue + margin;
  const innerMax = range.maxValue - margin;
  return price < innerMin || price > innerMax;
}

function candleEnvelope(candles: readonly HighLow[]): EntryAwareYRange | null {
  let minValue = Number.POSITIVE_INFINITY;
  let maxValue = Number.NEGATIVE_INFINITY;
  for (const candle of candles) {
    if (!Number.isFinite(candle.low) || !Number.isFinite(candle.high)) continue;
    if (candle.low < minValue) minValue = candle.low;
    if (candle.high > maxValue) maxValue = candle.high;
  }
  if (!Number.isFinite(minValue) || !Number.isFinite(maxValue)) return null;
  return { minValue, maxValue };
}

