        axisLabelVisible: false,
        color: "#EAB308",
        lineStyle: 2,
        price: 64_000,
      }),
    );
  });

  it("renders overlap-safe DOM labels for entry and current price", async () => {
    render(
      <TradeCardMiniChart
        candles={Array.from({ length: 30 }, (_, index) => miniCandleAt(index))}
        currentPrice={64_000.01}
        direction="CALL"
