describe("TradeCardMiniChart incremental rendering", () => {
  it("uses last-candle update only when earlier OHLC values are unchanged", () => {
    const previous = toLegacyMiniChartData(
      [miniCandleAt(0), miniCandleAt(1), miniCandleAt(2)],
      30,
      30,
    );
    const nextLastOnly = toLegacyMiniChartData(
      [
        miniCandleAt(0),
        miniCandleAt(1),
        { ...miniCandleAt(2), close: miniCandleAt(2).close + 10 },
      ],
      30,
      30,
    );
    const nextHistoricalCorrection = toLegacyMiniChartData(
      [
        miniCandleAt(0),
        { ...miniCandleAt(1), high: miniCandleAt(1).high + 10 },
        { ...miniCandleAt(2), close: miniCandleAt(2).close + 10 },
      ],
      30,
      30,
    );

    expect(canUpdateLastMiniCandle(previous, nextLastOnly)).toBe(true);
    expect(canUpdateLastMiniCandle(previous, nextHistoricalCorrection)).toBe(
      false,
    );
  });
});

