}

describe("TradeCardMiniChart chunked arrival", () => {
  beforeEach(() => {
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(
      {} as CanvasRenderingContext2D,
    );
    miniChartMocks.createChart.mockClear();
    miniChartMocks.chartApi.addCandlestickSeries.mockClear();
    miniChartMocks.chartApi.applyOptions.mockClear();
    miniChartMocks.chartApi.remove.mockClear();
    miniChartMocks.chartApi.timeScale.mockClear();
    miniChartMocks.seriesApi.createPriceLine.mockClear();
    miniChartMocks.seriesApi.removePriceLine.mockClear();
    miniChartMocks.seriesApi.setData.mockClear();
    miniChartMocks.seriesApi.update.mockClear();
    miniChartMocks.timeScaleApi.getVisibleLogicalRange.mockClear();
    miniChartMocks.timeScaleApi.setVisibleLogicalRange.mockClear();
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  // New threshold is 3 (MIN_CANDLES_FOR_TRADE_CHART = 3, P4 β/δ).
  // At 5 candles the gate is already met, so the first render already paints.
  it("paints when data arrives 5 → 10 → 30", () => {
    const { rerender } = render(
      <TradeCardMiniChart
        candles={makeCandles(5)}
        direction="CALL"
        minimumCandles={3}
      />,
    );
    rerender(
      <TradeCardMiniChart
        candles={makeCandles(10)}
        direction="CALL"
        minimumCandles={3}
      />,
    );
    rerender(
      <TradeCardMiniChart
        candles={makeCandles(30)}
        direction="CALL"
        minimumCandles={3}
      />,
    );

    const setDataCalls = miniChartMocks.seriesApi.setData.mock.calls;
    const nonEmptyCalls = setDataCalls.filter(
      (c) => Array.isArray(c[0]) && (c[0] as unknown[]).length > 0,
    );

    // At least one non-empty paint must have occurred (first at 5 candles).
    expect(nonEmptyCalls.length).toBeGreaterThanOrEqual(1);

    // No partial paint below the new threshold (3).
    for (const call of setDataCalls) {
      const len = Array.isArray(call[0]) ? (call[0] as unknown[]).length : 0;
      expect(len === 0 || len >= 3).toBe(true);
    }

    expect(miniChartMocks.seriesApi.update).not.toHaveBeenCalled();
  });

  it("paints once the threshold (3) is crossed during 0 → 2 → 3 → 4 arrival", () => {
    const { rerender } = render(
      <TradeCardMiniChart
        candles={makeCandles(0)}
        direction="CALL"
        minimumCandles={3}
      />,
    );
    rerender(
      <TradeCardMiniChart
        candles={makeCandles(2)}
        direction="CALL"
        minimumCandles={3}
      />,
    );
    rerender(
      <TradeCardMiniChart
        candles={makeCandles(3)}
        direction="CALL"
        minimumCandles={3}
      />,
    );
    rerender(
      <TradeCardMiniChart
        candles={makeCandles(4)}
        direction="CALL"
        minimumCandles={3}
      />,
    );

    const setDataCalls = miniChartMocks.seriesApi.setData.mock.calls;

    // No setData call should have a length between 1 and 2 (below new threshold).
    for (const call of setDataCalls) {
      const len = Array.isArray(call[0]) ? (call[0] as unknown[]).length : 0;
      expect(len === 0 || len >= 3).toBe(true);
    }

    // The 3-candle step must produce a non-empty paint.
    const nonEmptyCalls = setDataCalls.filter(
      (c) => Array.isArray(c[0]) && (c[0] as unknown[]).length > 0,
    );
    expect(nonEmptyCalls.length).toBeGreaterThanOrEqual(1);

    // After 4 candles: either setData(3+ sliced) or update(last-only change) is acceptable.
    const updateCount = miniChartMocks.seriesApi.update.mock.calls.length;
    const setDataCount = nonEmptyCalls.length;
    expect(updateCount + setDataCount).toBeGreaterThanOrEqual(1);
  });

  it("clears chart when data shrinks 3 → 1 → 3", () => {
    const { rerender } = render(
      <TradeCardMiniChart
        candles={makeCandles(3)}
        direction="CALL"
        minimumCandles={3}
      />,
    );

    // First render: threshold met — chart paints with 3.
    const firstNonEmpty = miniChartMocks.seriesApi.setData.mock.calls.find(
      (c) => Array.isArray(c[0]) && (c[0] as unknown[]).length > 0,
    );
    expect((firstNonEmpty![0] as unknown[]).length).toBe(3);

    miniChartMocks.seriesApi.setData.mockClear();

    // Second render: only 1 candle — below minimumCandles(3). Keep the last
    // valid snapshot mounted instead of flashing the loading fallback.
    rerender(
      <TradeCardMiniChart
        candles={makeCandles(1)}
        direction="CALL"
        minimumCandles={3}
        isLoading
      />,
    );
    const callsAfterShrink = miniChartMocks.seriesApi.setData.mock.calls;

    for (const call of callsAfterShrink) {
      const len = Array.isArray(call[0]) ? (call[0] as unknown[]).length : 0;
      expect(len).toBeGreaterThanOrEqual(3);
    }
    expect(screen.queryByText("Carregando mercado...")).toBeNull();
    expect(screen.getByTestId("active-trade-chart")).toHaveAttribute(
      "data-visual-ready",
      "true",
    );

    miniChartMocks.seriesApi.setData.mockClear();

    // Third render: 3 again — repaint with full window.
    rerender(
      <TradeCardMiniChart
        candles={makeCandles(3)}
        direction="CALL"
        minimumCandles={3}
      />,
    );
    expect(
      document.querySelector('[data-testid="active-trade-chart"]'),
    ).toHaveAttribute("data-candle-count", "3");
  });

  it("respects minimumCandles=12 override across 5 → 12 → 13", () => {
    const { rerender } = render(
      <TradeCardMiniChart
        candles={makeCandles(5)}
        minimumCandles={12}
        direction="CALL"
      />,
    );

    // At 5 candles (below minimumCandles=12): no non-empty paint.
    const callsAt5 = miniChartMocks.seriesApi.setData.mock.calls;
    for (const call of callsAt5) {
      const len = Array.isArray(call[0]) ? (call[0] as unknown[]).length : 0;
      expect(len).toBe(0);
    }

    // The root div must advertise the override.
    const { getByTestId } = {
      getByTestId: (id: string) =>
        document.querySelector(`[data-testid="${id}"]`)!,
    };
    const chart = getByTestId("active-trade-chart");
    expect(chart).toHaveAttribute("data-min-candles", "12");

    miniChartMocks.seriesApi.setData.mockClear();

    // At exactly 12 candles: gate met, paint occurs.
    rerender(
      <TradeCardMiniChart
        candles={makeCandles(12)}
        minimumCandles={12}
        direction="CALL"
      />,
    );
    const callsAt12 = miniChartMocks.seriesApi.setData.mock.calls;
    const nonEmptyAt12 = callsAt12.find(
      (c) => Array.isArray(c[0]) && (c[0] as unknown[]).length > 0,
    );
    expect((nonEmptyAt12![0] as unknown[]).length).toBe(12);

    miniChartMocks.seriesApi.setData.mockClear();
    miniChartMocks.seriesApi.update.mockClear();

    // At 13 candles: either update (last-only change) or setData capped to maxCandles.
    rerender(
      <TradeCardMiniChart
        candles={makeCandles(13)}
        minimumCandles={12}
        direction="CALL"
      />,
    );
    const updateCount = miniChartMocks.seriesApi.update.mock.calls.length;
    const setDataNonEmpty = miniChartMocks.seriesApi.setData.mock.calls.filter(
      (c) => Array.isArray(c[0]) && (c[0] as unknown[]).length > 0,
    );
    // One of the two paths must have been taken.
    expect(updateCount + setDataNonEmpty.length).toBeGreaterThanOrEqual(1);
  });
});

